const STAGES = [
  { key: 'pending', label: '待投递' },
  { key: 'applied', label: '已投递' },
  { key: 'interview', label: '面试中' },
  { key: 'closed', label: '已结束' }
];
const STAGE_KEYS = STAGES.map(s => s.key);
const STAGE_LABEL = {};
STAGES.forEach(s => { STAGE_LABEL[s.key] = s.label; });

const el = {
  list: document.querySelector('[data-role="list"]'),
  empty: document.querySelector('[data-role="empty"]'),
  error: document.querySelector('[data-role="error"]'),
  formMask: document.querySelector('[data-role="form-mask"]'),
  form: document.querySelector('[data-role="form"]'),
  formTitle: document.querySelector('[data-role="form-title"]'),
  formError: document.querySelector('[data-role="form-error"]'),
  formSubmit: document.querySelector('[data-role="form-submit"]'),
  fCompany: document.querySelector('[data-role="f-company"]'),
  fPosition: document.querySelector('[data-role="f-position"]'),
  fDate: document.querySelector('[data-role="f-date"]'),
  fStage: document.querySelector('[data-role="f-stage"]'),
  fNote: document.querySelector('[data-role="f-note"]'),
  confirmMask: document.querySelector('[data-role="confirm-mask"]'),
  confirmText: document.querySelector('[data-role="confirm-text"]')
};

let state = null;
let filter = 'all';
let editingId = null;
let pendingDeleteId = null;

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : 'pending';
}

function normalizeRecord(raw) {
  const rec = (raw && typeof raw === 'object') ? raw : {};
  return {
    id: typeof rec.id === 'string' && rec.id ? rec.id : makeId(),
    company: typeof rec.company === 'string' ? rec.company : '',
    position: typeof rec.position === 'string' ? rec.position : '',
    date: typeof rec.date === 'string' ? rec.date : '',
    stage: normalizeStage(rec.stage),
    note: typeof rec.note === 'string' ? rec.note : ''
  };
}

function makeId() {
  return 'r' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

function todayStr() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function showError(msg) {
  if (!msg) {
    el.error.hidden = true;
    el.error.textContent = '';
    return;
  }
  el.error.textContent = msg;
  el.error.hidden = false;
}

function showFormError(msg) {
  if (!msg) {
    el.formError.hidden = true;
    el.formError.textContent = '';
    return;
  }
  el.formError.textContent = msg;
  el.formError.hidden = false;
}

function countByStage() {
  const counts = { all: state.records.length, pending: 0, applied: 0, interview: 0, closed: 0 };
  state.records.forEach(r => {
    const key = normalizeStage(r.stage);
    counts[key] += 1;
  });
  return counts;
}

function renderStats() {
  const counts = countByStage();
  Object.keys(counts).forEach(key => {
    const node = document.querySelector('[data-stat-num="' + key + '"]');
    if (node) node.textContent = String(counts[key]);
  });
}

function renderFilters() {
  const buttons = document.querySelectorAll('.filter-btn');
  buttons.forEach(btn => {
    const active = btn.getAttribute('data-filter') === filter;
    btn.classList.toggle('is-active', active);
    btn.setAttribute('aria-pressed', active ? 'true' : 'false');
  });
}

function buildRecordCard(record) {
  const li = document.createElement('li');
  li.className = 'record-card';
  li.setAttribute('data-stage', normalizeStage(record.stage));

  const head = document.createElement('div');
  head.className = 'record-head';

  const titleBox = document.createElement('div');
  const company = document.createElement('h3');
  company.className = 'record-company';
  company.textContent = record.company || '（未填写公司）';
  const position = document.createElement('p');
  position.className = 'record-position';
  position.textContent = record.position || '（未填写岗位）';
  titleBox.appendChild(company);
  titleBox.appendChild(position);

  const tag = document.createElement('span');
  tag.className = 'stage-tag';
  tag.setAttribute('data-stage', normalizeStage(record.stage));
  tag.textContent = STAGE_LABEL[normalizeStage(record.stage)];

  head.appendChild(titleBox);
  head.appendChild(tag);
  li.appendChild(head);

  const meta = document.createElement('p');
  meta.className = 'record-meta';
  meta.textContent = '投递日期：' + (record.date ? record.date : '未填写');
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost btn-sm';
  editBtn.textContent = '编辑';
  editBtn.addEventListener('click', () => openForm(record.id));

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-ghost btn-sm';
  delBtn.textContent = '删除';
  delBtn.addEventListener('click', () => openConfirm(record.id));

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const records = state.records.filter(r => filter === 'all' || normalizeStage(r.stage) === filter);
  el.list.textContent = '';
  records.forEach(r => el.list.appendChild(buildRecordCard(r)));

  if (records.length === 0) {
    el.empty.hidden = false;
    if (state.records.length === 0) {
      el.empty.textContent = '还没有投递记录，点击「新增投递」开始记录吧。';
    } else {
      el.empty.textContent = '当前筛选下没有记录，试试切换其他阶段。';
    }
  } else {
    el.empty.hidden = true;
  }
}

function render() {
  renderStats();
  renderFilters();
  renderList();
}

async function persist(nextRecords, successMsg) {
  const next = Object.assign({}, state, { records: nextRecords });
  try {
    await appStore.setState(next);
    state = next;
    showError('');
    render();
    return true;
  } catch (err) {
    showError((successMsg ? successMsg + '失败：' : '保存失败：') + (err && err.message ? err.message : '未知错误'));
    return false;
  }
}

function openForm(id) {
  editingId = id || null;
  showFormError('');
  if (editingId) {
    const rec = state.records.find(r => r.id === editingId);
    if (!rec) {
      editingId = null;
      return;
    }
    el.formTitle.textContent = '编辑投递';
    el.formSubmit.textContent = '保存修改';
    el.fCompany.value = rec.company;
    el.fPosition.value = rec.position;
    el.fDate.value = rec.date;
    el.fStage.value = normalizeStage(rec.stage);
    el.fNote.value = rec.note;
  } else {
    el.formTitle.textContent = '新增投递';
    el.formSubmit.textContent = '保存';
    el.form.reset();
    el.fDate.value = todayStr();
    el.fStage.value = 'pending';
  }
  el.formMask.hidden = false;
  el.fCompany.focus();
}

function closeForm() {
  el.formMask.hidden = true;
  editingId = null;
  showFormError('');
  el.form.reset();
}

function openConfirm(id) {
  const rec = state.records.find(r => r.id === id);
  if (!rec) return;
  pendingDeleteId = id;
  el.confirmText.textContent = '确定要删除「' + (rec.company || '未填写公司') + ' · ' + (rec.position || '未填写岗位') + '」这条投递记录吗？删除后无法恢复。';
  el.confirmMask.hidden = false;
}

function closeConfirm() {
  el.confirmMask.hidden = true;
  pendingDeleteId = null;
}

async function handleSubmit(event) {
  event.preventDefault();
  const company = el.fCompany.value.trim();
  const position = el.fPosition.value.trim();
  const date = el.fDate.value;
  const stage = normalizeStage(el.fStage.value);
  const note = el.fNote.value.trim();

  if (!company) {
    showFormError('请填写公司名称。');
    el.fCompany.focus();
    return;
  }
  if (!position) {
    showFormError('请填写岗位名称。');
    el.fPosition.focus();
    return;
  }
  showFormError('');

  let nextRecords;
  if (editingId) {
    nextRecords = state.records.map(r => {
      if (r.id !== editingId) return r;
      return Object.assign({}, r, { company, position, date, stage, note });
    });
  } else {
    nextRecords = state.records.concat([{
      id: makeId(),
      company, position, date, stage, note
    }]);
  }

  const ok = await persist(nextRecords, editingId ? '保存修改' : '新增记录');
  if (ok) closeForm();
}

async function handleConfirmDelete() {
  if (!pendingDeleteId) return;
  const id = pendingDeleteId;
  const nextRecords = state.records.filter(r => r.id !== id);
  const ok = await persist(nextRecords, '删除记录');
  if (ok) closeConfirm();
}

function bindEvents() {
  document.querySelector('[data-action="add"]').addEventListener('click', () => openForm(null));
  document.querySelector('[data-action="form-cancel"]').addEventListener('click', closeForm);
  document.querySelector('[data-action="confirm-cancel"]').addEventListener('click', closeConfirm);
  document.querySelector('[data-action="confirm-ok"]').addEventListener('click', handleConfirmDelete);
  el.form.addEventListener('submit', handleSubmit);

  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      filter = btn.getAttribute('data-filter') || 'all';
      render();
    });
  });

  el.formMask.addEventListener('click', e => {
    if (e.target === el.formMask) closeForm();
  });
  el.confirmMask.addEventListener('click', e => {
    if (e.target === el.confirmMask) closeConfirm();
  });
  document.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    if (!el.confirmMask.hidden) closeConfirm();
    else if (!el.formMask.hidden) closeForm();
  });
}

async function init() {
  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (err) {
    raw = null;
  }
  const base = (raw && typeof raw === 'object') ? raw : {};
  const rawRecords = Array.isArray(base.records) ? base.records : [];
  state = Object.assign({}, base, { records: rawRecords.map(normalizeRecord) });

  bindEvents();
  render();

  if (!Array.isArray(base.records)) {
    try {
      await appStore.setState(Object.assign({}, state));
    } catch (err) {
      showError('初始化数据失败：' + (err && err.message ? err.message : '未知错误'));
    }
  }
}

await init();

