:root {
  --blue-900: #0f2f66;
  --blue-700: #1a4fa0;
  --blue-600: #2563c9;
  --blue-500: #3b82f6;
  --blue-100: #e3edfd;
  --blue-50: #f2f7ff;
  --line: #d8e3f5;
  --text: #1c2b45;
  --text-soft: #5b6b86;
  --white: #ffffff;
  --danger: #d64545;
  --danger-soft: #fdecec;
  --radius: 12px;
  --shadow: 0 2px 10px rgba(26, 79, 160, 0.08);
}

* { box-sizing: border-box; }

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 16px 14px 40px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  color: var(--text);
  background: var(--blue-50);
  min-height: 100vh;
  -webkit-text-size-adjust: 100%;
}

.topbar { padding: 6px 2px 14px; }

.title {
  margin: 0;
  font-size: 22px;
  font-weight: 700;
  color: var(--blue-900);
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--text-soft);
}

.stats {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}

.stat-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 10px 4px;
  text-align: center;
  box-shadow: var(--shadow);
}

.stat-num {
  display: block;
  font-size: 20px;
  font-weight: 700;
  color: var(--blue-600);
  line-height: 1.2;
}

.stat-label {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--text-soft);
  white-space: nowrap;
}

.toolbar {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 12px;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-btn {
  flex: 1 1 auto;
  min-width: 64px;
  padding: 8px 10px;
  font-size: 13px;
  color: var(--blue-700);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.filter-btn:hover { background: var(--blue-100); }

.filter-btn.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: var(--white);
  font-weight: 600;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  min-height: 42px;
}

.btn-primary {
  background: var(--blue-600);
  color: var(--white);
  font-weight: 600;
}

.btn-primary:hover { background: var(--blue-700); }

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--line);
}

.btn-ghost:hover { background: var(--blue-100); }

.btn-danger {
  background: var(--danger);
  color: var(--white);
  font-weight: 600;
}

.btn-danger:hover { background: #b93a3a; }

.btn-sm {
  padding: 7px 12px;
  font-size: 13px;
  min-height: 36px;
}

.error-banner {
  margin: 0 0 12px;
  padding: 10px 12px;
  font-size: 13px;
  color: #8a2020;
  background: var(--danger-soft);
  border: 1px solid #f3c9c9;
  border-radius: 10px;
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: var(--radius);
  padding: 12px 12px 10px;
  box-shadow: var(--shadow);
}

.record-card[data-stage="pending"] { border-left-color: #8fa6c9; }
.record-card[data-stage="applied"] { border-left-color: var(--blue-500); }
.record-card[data-stage="interview"] { border-left-color: #f0a92c; }
.record-card[data-stage="closed"] { border-left-color: #9aa7b8; }

.record-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.record-company {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--blue-900);
  word-break: break-word;
}

.record-position {
  margin: 4px 0 0;
  font-size: 13px;
  color: var(--text-soft);
  word-break: break-word;
}

.stage-tag {
  flex: 0 0 auto;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 999px;
  white-space: nowrap;
  background: var(--blue-100);
  color: var(--blue-700);
}

.stage-tag[data-stage="pending"] { background: #eef1f6; color: #5b6b86; }
.stage-tag[data-stage="applied"] { background: var(--blue-100); color: var(--blue-700); }
.stage-tag[data-stage="interview"] { background: #fdf1d8; color: #9a6a10; }
.stage-tag[data-stage="closed"] { background: #eceff3; color: #6b7787; }

.record-meta {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--text-soft);
}

.record-note {
  margin: 8px 0 0;
  padding: 8px 10px;
  font-size: 13px;
  line-height: 1.5;
  color: var(--text);
  background: var(--blue-50);
  border-radius: 8px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
}

.empty-hint {
  margin: 24px 0;
  padding: 26px 16px;
  text-align: center;
  font-size: 14px;
  color: var(--text-soft);
  background: var(--white);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
}

.modal-mask {
  position: fixed;
  inset: 0;
  background: rgba(15, 47, 102, 0.42);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
}

.modal-mask[hidden] { display: none; }

.modal {
  width: 100%;
  max-width: 460px;
  max-height: 88vh;
  overflow-y: auto;
  background: var(--white);
  border-radius: 14px;
  padding: 18px 16px 16px;
  box-shadow: 0 12px 32px rgba(15, 47, 102, 0.24);
}

.modal-sm { max-width: 360px; }

.modal-title {
  margin: 0 0 14px;
  font-size: 17px;
  font-weight: 700;
  color: var(--blue-900);
}

.form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
}

.req { color: var(--danger); font-style: normal; }

.field input,
.field select,
.field textarea {
  width: 100%;
  padding: 10px 12px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.field textarea { resize: vertical; min-height: 72px; }

.field input:focus,
.field select:focus,
.field textarea:focus {
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.16);
}

.form-error {
  margin: 0;
  padding: 8px 10px;
  font-size: 13px;
  color: #8a2020;
  background: var(--danger-soft);
  border-radius: 8px;
}

.confirm-text {
  margin: 0 0 16px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--text);
  word-break: break-word;
}

.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

@media (max-width: 420px) {
  .stats { grid-template-columns: repeat(3, 1fr); }
  .stat-card:first-child { grid-column: span 3; }
  .filter-btn { flex: 1 1 30%; }
  .toolbar .btn-primary { width: 100%; }
  .record-actions .btn { flex: 1 1 auto; }
}
